function localizeStageOptions(){
  const labels={en:['Primary 1–3','Primary 3–6','Middle 1–2','Grade 9–12','Prefer not to say'],'zh-CN':['小学 1–3 年级','小学 3–6 年级','初中 1–2 年级','初三–高中三年级','不提供'],'zh-TW':['國小 1–3 年級','國小 3–6 年級','國中 1–2 年級','高中–高三年級','不提供'],fr:['Primaire 1–3','Primaire 3–6','Collège 1–2','3e – Terminale','Ne pas préciser'],de:['Grundschule 1–3','Grundschule 3–6','Mittelschule 1–2','Klasse 9–12','Nicht angeben'],es:['Primaria 1–3','Primaria 3–6','Secundaria 1–2','Grados 9–12','No indicar'],it:['Primaria 1–3','Primaria 3–6','Scuola media 1–2','Classi 9–12','Non specificare'],ar:['المرحلة الابتدائية 1–3','المرحلة الابتدائية 3–6','المرحلة المتوسطة 1–2','الصفوف 9–12','عدم التحديد'],ja:['小学1〜3年','小学3〜6年','中学1〜2年','高校1〜3年','回答しない'],ko:['초등 1-3','초등 3-6','중학교 1-2','고등학교 1-3','응답하지 않음'],fa:['ابتدایی ۱–۳','ابتدایی ۳–۶','متوسطه ۱–۲','دبیرستان ۹–۱۲','ترجیح می‌دهم نگویم']}[currentLang] || [];
  const select=$('stage');
  if(select && labels.length){Array.from(select.options).forEach((opt,i)=>{if(labels[i]!==undefined)opt.textContent=labels[i];});}
  const roleLabels={en:['Parent / guardian','Adult / learner'],'zh-CN':['家长 / 监护人','成人 / 学习者'],'zh-TW':['家長 / 監護人','成人 / 學習者'],fr:['Parent / tuteur','Adulte / apprenant'],de:['Elternteil / Vormund','Erwachsener / Lernender'],es:['Padre / tutor','Adulto / estudiante'],it:['Genitore / tutore','Adulto / studente'],ar:['ولي الأمر / الوصي','بالغ / متعلم'],ja:['保護者','成人学習者'],ko:['부모 / 보호자','성인 / 학습자'],fa:['والدین / سرپرست','بزرگسال / یادگیرنده']}[currentLang]||[];
  const role=$('signupRole');
  if(role && roleLabels.length)Array.from(role.options).forEach((opt,i)=>{if(roleLabels[i]!==undefined)opt.textContent=roleLabels[i];});
}
function applyLang(lang){
  currentLang=T[lang]?lang:'en';
  try{localStorage.setItem('calcelf_lang',currentLang)}catch{}
  document.documentElement.lang=currentLang;
  document.documentElement.dir=(currentLang==='ar'||currentLang==='fa')?'rtl':'ltr';
  window.CALF_LANG=currentLang;
  try{window.calfRefreshI18n&&window.calfRefreshI18n(currentLang)}catch{}
  setText('langLabel',LANG_NAMES[currentLang]||currentLang);
  const menu=$('langMenu'), langBtn=$('langBtn');
  if(menu)menu.classList.remove('open');
  if(langBtn)langBtn.setAttribute('aria-expanded','false');
  setText('tagline',t('tag'));setText('heroTitle',t('hero'));setText('heroDesc',t('desc'));
  setText('stageLabel',t('stage'));setText('stageHint',t('stageHint'));setText('animLabel',t('anim'));setText('animCb',t('animCb'));setText('animHint',t('animHint'));
  setText('imgLabel',t('img'));setText('uploadBig',t('upload'));setText('uploadSmall',t('uploadSmall'));setText('removeBtn',t('remove'));setText('textLabel',t('text'));setPlaceholder('text',t('placeholder'));
  setText('voiceBtn',t('voice'));setText('voiceStatus',t('voiceIdle'));setText('solveBtn',t('solve'));setHtml('privacyLine',t('privacy'));setText('loadingText',t('loading'));
  setText('resultTitle',t('result'));setText('solutionTitle',t('solutions'));setText('animTitle',t('visual'));setText('animOptional',t('optional'));setText('chatTitle',t('chat'));setText('chatPill',t('chatPill'));setPlaceholder('chatInput',t('chatPlaceholder'));setText('sendChat',t('send'));
  setText('practiceTitle',t('practice'));setText('practicePill',t('practicePill'));setText('practiceDesc',t('practiceDesc'));setText('practice1',t('level1'));setText('practice2',t('level2'));setText('practice3',t('level3'));
  setText('creditsTitle',t('credits'));setText('creditsLabel',t('creditsLabel'));setText('starsLabel',t('stars'));setText('levelLabel',t('lifetime'));setText('buyBtn',t('buy'));setText('billingBtn',t('manage'));
  setText('styleTitle',t('style'));setText('styleSummary',t('styleDesc'));setText('rewardsTitle',t('rewards'));setText('rewardsDesc',t('rewardsDesc'));setText('rewardsBtn',t('viewRewards'));setText('inviteTitle',t('invite'));setText('inviteDesc',t('inviteDesc'));setText('inviteBtn',t('myInvite'));setText('privacyTitle',t('privacyTitle'));setText('privacyDesc',t('privacyDesc'));setText('footerText',t('footer'));
  const FOOT={'en':['Privacy','Terms'],'zh-CN':['隐私政策','服务条款'],'zh-TW':['隱私政策','服務條款'],ja:['プライバシー','利用規約'],ko:['개인정보 보호','이용약관'],fr:['Confidentialité','Conditions'],de:['Datenschutz','AGB'],es:['Privacidad','Términos'],it:['Privacy','Termini'],ar:['الخصوصية','الشروط'],fa:['حریم خصوصی','قوانین']}[currentLang]||['Privacy','Terms'];
  setText('footerPrivacy',FOOT[0]);setText('footerTerms',FOOT[1]);
  setText('accountBtn',t('account'));/* branded title handled in localizeAuth */setText('accountModalDesc',t('accountDesc'));setPlaceholder('email',t('email'));setText('plansTitle',t('plans'));setText('plansDesc',t('plansDesc'));setText('topupTitle',t('topup'));setText('inviteModalTitle',t('inviteTitle'));setText('inviteModalDesc',t('inviteDesc'));setText('convertStars',t('convert'));
  localizeStageOptions();
  document.querySelectorAll('#langMenu button').forEach(b=>{const active=b.dataset.lang===currentLang;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'true':'false');});
  applyStage($('stage')?.value);localizePlans();applyCreditMembershipLocale();
  try{calfApplyTitleIcons();}catch(e){console.warn('title icons',e);}
  try{refreshNoteModeUI();}catch(e){}
  try{ document.dispatchEvent(new Event('calf:langchanged')); }catch(e){}
}
