// v5.5.2: per-stage UI font scaling (whole-page zoom, works with px-based CSS)
const STAGE_FONT_SCALE={'primary_1_3':1.28,'primary_3_6':1.18,'middle_1_2':1.05,'grade_9_12':1.04,'prefer_not':1};
function applyStage(stage){
  document.body.dataset.stage=stage||'prefer_not';
  // zoom 只作用于应用内容包裹层，固定定位的弹窗留在包裹层外，避免 body zoom 下弹窗偏移/溢出
  var z=STAGE_FONT_SCALE[stage]||1;
  var wrap=document.getElementById('appZoomWrap');
  try{
    if(wrap){wrap.style.zoom=String(z);document.body.style.zoom='1';}
    else{document.body.style.zoom=String(z);}
  }catch(e){}
  const s=STAGE_THEME[stage]||STAGE_THEME.prefer_not;
  setText('styleSummary',t('styleDesc')+' '+s.desc);
}
function token(){
  if(!window.turnstile) return null;
  if(window.tsWidget){ try { return window.turnstile.getResponse(window.tsWidget); } catch(e) { console.warn('Turnstile main widget error:', e); } }
  if(window.authTsWidget){ try { return window.turnstile.getResponse(window.authTsWidget); } catch(e) { console.warn('Turnstile auth widget error:', e); } }
  return null;
}
async function loadConfig(){
  const r=await fetch('/api/public-config');cfg=await r.json();
  if(typeof supabase !== 'undefined'){ sb=supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey); window.sb=sb; window.calfSignOut=async()=>{try{await sb.auth.signOut();}catch(e){console.error('signOut',e);} location.reload();}; }
  initTurnstile();
  await refresh();
  if (window.location.hash && window.location.hash.includes('access_token')) {
    setTimeout(() => { triggerWelcomeCeremony(); window.history.replaceState(null, null, window.location.pathname); }, 1000);
  }
}
function initTurnstile(){
  if(!cfg.turnstileSiteKey) return;
  if(!window.turnstile){ setTimeout(initTurnstile, 600); return; }
  const box = $('turnstileBox');
  if(box){ try { if(window.tsWidget) window.turnstile.remove(window.tsWidget); box.innerHTML=''; window.tsWidget = window.turnstile.render(box, {sitekey:cfg.turnstileSiteKey,theme:'light',size:'flexible'}); } catch(e) { console.warn('Turnstile main render error:', e); } }
  const authBox = $('authTurnstile');
  if(authBox){ try { if(window.authTsWidget) window.turnstile.remove(window.authTsWidget); authBox.innerHTML=''; window.authTsWidget = window.turnstile.render(authBox, {sitekey:cfg.turnstileSiteKey,theme:'light',size:'flexible'}); } catch(e) { console.warn('Turnstile auth render error:', e); } }
}
async function session(){if(!sb)return null;return (await sb.auth.getSession()).data.session}
function authHeader(s){return {Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'}}

async function refresh(){
  if(!sb)return;
  const s=await session();
  const privacyRow = document.getElementById('privacyRow');

  if(!s){
    setText('credits','—');
    setText('stars','0');
    setText('accountBtn',t('account'));
    try{ window.calfHeaderSetAnonymous&&window.calfHeaderSetAnonymous(); }catch(e){}
    // 未登录（理论上不会出现，因为会自动匿名登录）：隐私行按匿名用户显示
    if(privacyRow) privacyRow.style.display = 'flex';
    return;
  }

  // 只有匿名用户才显示隐私行；注册/登录用户整行隐藏
  const isAnonymous = s.user && s.user.is_anonymous;
  if(privacyRow){
    privacyRow.style.display = isAnonymous ? 'flex' : 'none';
  }

  const r=await fetch('/api/profile',{headers:{Authorization:`Bearer ${s.access_token}`}});
  if(r.ok){const j=await r.json();currentProfile=j.profile;lastProfile=j.profile;applyStage(j.profile.stage_band);applyMembership(j.profile.lifetime_level,j.profile.monthly_level);calcelfRenderAvatar(j.profile);renderMembershipCard(j.profile);setText('accountBtn',t('account')+' ✓');
      if(!isAnonymous){ try{ window.calfHeaderSetUser&&window.calfHeaderSetUser(j.profile); }catch(e){} } else { try{ window.calfHeaderSetAnonymous&&window.calfHeaderSetAnonymous(); }catch(e){} }
    } else { if(isAnonymous){ try{ window.calfHeaderSetAnonymous&&window.calfHeaderSetAnonymous(); }catch(e){} } }
  const c=await fetch('/api/credits',{headers:{Authorization:`Bearer ${s.access_token}`}});
  if(c.ok){const j=await c.json();const isAdult=currentProfile?.account_role==='adult'||currentProfile?.account_role==='parent';window.__lastCreditsSnapshot={total:j.total||0,isAdult,grant:j.monthly_grant||100,plan:j.plan||'free'};calcelfUpdateCreditMeter(j.total||0,isAdult,j.monthly_grant||100,j.plan||'free',currentProfile);setText('stars',j.stars||0);setText('lifetimeLevel',j.lifetime_level||1);setText('monthlyLevel',j.monthly_level||1);setText('planPill',j.plan||'free')}
}
async function useCareReset(){const s=await session();if(!s)return;const r=await fetch('/api/loyalty-reset',{method:'POST',headers:authHeader(s)}),j=await r.json();if(!r.ok){toast(j.error||t('genericError'));return}toast('✓ '+creditUi().care);await refresh()}
function applyMembership(lifetime,monthly){document.body.dataset.lifetime=String(lifetime||1);document.body.dataset.monthly=String(monthly||1)}

/* =========================================================
   CalcElf 隐私强制阅读模块（打开即计时 + 滚动到底 + 5秒后解锁 + 同意后自动勾选主界面）
   ========================================================= */
(function(){
  const LS_KEY='calcelf_privacy_agreed_v1';
  const META_KEY='calcelf_privacy_consent_meta';
  let pendingResolve=null, timer=null, startTime=0, scrolledToBottom=false, agreed=false, parentAgreed=false;

  function getText(){
    if(window.PRIVACY_TEXTS && window.PRIVACY_TEXTS.get) return window.PRIVACY_TEXTS.get();
    if(window.PRIVACY_TEXTS) return window.PRIVACY_TEXTS[currentLang] || window.PRIVACY_TEXTS.en;
    return {title:'Privacy',body:'',scrollHint:'Please scroll down',checkboxText:'I agree.',parentText:'',agreeBtn:'Agree',waitText:'Please wait',readBtn:'Confirm',closeBtn:'Close',ui:{}};
  }

  function updateState(){
    const cb = document.getElementById('privacyAgreeCheckbox');
    const pcb = document.getElementById('privacyParentCheckbox');
    const btn = document.getElementById('privacySubmitBtn');
    const statusBar = document.getElementById('privacyStatusBar');
    const label = document.getElementById('privacyCheckboxLabel');
    const plabel = document.getElementById('privacyParentLabel');
    const tt = getText();
    const ui = tt.ui || {};

    const elapsed = startTime ? (Date.now() - startTime) / 1000 : 0;
    const remaining = Math.max(0, Math.ceil(5 - elapsed));
    const timeOk = elapsed >= 5;
    const canProceed = scrolledToBottom && timeOk;

    if(statusBar){
      if(!scrolledToBottom && !timeOk){
        statusBar.textContent = (tt.overlayHint || tt.scrollHint || 'Please scroll to the bottom') + ' · ' + remaining + 's';
        statusBar.style.color = '#e74c3c';
      } else if(!scrolledToBottom){
        statusBar.textContent = tt.overlayHint || tt.scrollHint || 'Please scroll to the bottom';
        statusBar.style.color = '#e74c3c';
      } else if(!timeOk){
        statusBar.textContent = (tt.waitText || 'Please keep reading') + ' (' + remaining + 's)';
        statusBar.style.color = '#f39c12';
      } else if(!agreed || !parentAgreed){
        statusBar.textContent = '⚠️ ' + (tt.parentReq || ui.parentReq || 'Please tick both confirmations.');
        statusBar.style.color = '#f39c12';
      } else {
        statusBar.textContent = '✅ ' + (tt.readBtn || ui.confirm || 'Confirm');
        statusBar.style.color = '#27ae60';
      }
    }
    if(cb) cb.disabled = !canProceed;
    if(pcb) pcb.disabled = !canProceed;
    if(btn){
      btn.disabled = !(canProceed && agreed && parentAgreed);
      btn.style.opacity = btn.disabled ? '0.5' : '1';
      btn.textContent = btn.disabled ? (tt.agreeBtn || ui.agree || 'Agree') : (tt.readBtn || ui.confirm || 'Confirm');
    }
    if(label){
      label.style.opacity = canProceed ? '1' : '0.4';
      label.style.pointerEvents = canProceed ? 'auto' : 'none';
    }
    if(plabel){
      plabel.style.opacity = canProceed ? '1' : '0.4';
      plabel.style.pointerEvents = canProceed ? 'auto' : 'none';
    }
  }

  function lockBackgroundScroll(){
    // 记录原值，避免覆盖其他模块设置；弹窗打开期间禁止背景页面滚动。
    // 采用 position:fixed 锁定（同时兼容 iOS 橡皮筋、以及 body zoom 下 fixed 弹窗偏移问题）。
    if(document.body.dataset.cePrivacyLocked === '1') return;
    document.body.dataset.cePrevOverflow = document.body.style.overflow || '';
    document.body.dataset.cePrevHtmlOverflow = document.documentElement.style.overflow || '';
    document.body.dataset.cePrevPos = document.body.style.position || '';
    document.body.dataset.cePrevTop = document.body.style.top || '';
    document.body.dataset.cePrevLeft = document.body.style.left || '';
    document.body.dataset.cePrevRight = document.body.style.right || '';
    document.body.dataset.cePrevWidth = document.body.style.width || '';
    var y = window.pageYOffset || document.documentElement.scrollTop || 0;
    document.body.dataset.ceLockY = String(y);
    document.body.style.overflow = 'hidden';
    document.documentElement.style.overflow = 'hidden';
    document.body.style.position = 'fixed';
    document.body.style.top = (-y) + 'px';
    document.body.style.left = '0';
    document.body.style.right = '0';
    document.body.style.width = '100%';
    document.body.dataset.cePrivacyLocked = '1';
  }
  function unlockBackgroundScroll(){
    if(document.body.dataset.cePrivacyLocked !== '1') return;
    var y = parseInt(document.body.dataset.ceLockY || '0', 10) || 0;
    document.body.style.overflow = document.body.dataset.cePrevOverflow || '';
    document.documentElement.style.overflow = document.body.dataset.cePrevHtmlOverflow || '';
    document.body.style.position = document.body.dataset.cePrevPos || '';
    document.body.style.top = document.body.dataset.cePrevTop || '';
    document.body.style.left = document.body.dataset.cePrevLeft || '';
    document.body.style.right = document.body.dataset.cePrevRight || '';
    document.body.style.width = document.body.dataset.cePrevWidth || '';
    delete document.body.dataset.cePrivacyLocked;
    window.scrollTo(0, y);
  }

  function open(){
    const modal = document.getElementById('privacyModal');
    if(!modal) return;
    const tt = getText();
    lockBackgroundScroll();

    const titleEl = document.getElementById('privacyTitle');
    const bodyEl = document.getElementById('privacyBody');
    const checkboxTextEl = document.getElementById('privacyCheckboxText');
    const scrollArea = document.getElementById('privacyScrollArea');
    const overlay = document.getElementById('scrollOverlay');
    const cb = document.getElementById('privacyAgreeCheckbox');
    const pcb = document.getElementById('privacyParentCheckbox');
    const submitBtn = document.getElementById('privacySubmitBtn');
    const closeBtn = document.getElementById('privacyCloseBtn');

    if(closeBtn){
      closeBtn.onclick = function(){ close(false); };
    }

    if(titleEl) titleEl.textContent = tt.title;
    if(checkboxTextEl) checkboxTextEl.textContent = tt.checkboxText || (tt.ui&&tt.ui.consent1Hint) || 'I have read and understood the Privacy Notice.';
    const parentTextEl=document.getElementById('privacyParentText');
    const parentHintEl=document.getElementById('privacyParentHint');
    if(parentTextEl) parentTextEl.textContent = tt.parentText || '';
    if(parentHintEl) parentHintEl.textContent = (tt.ui&&tt.ui.consent2Hint) || '';
    const overlayTextEl=document.getElementById('privacyOverlayText');
    if(overlayTextEl) overlayTextEl.textContent = tt.overlayHint || tt.scrollHint || '';
    const centerLink=document.getElementById('privacyCenterLink');
    if(centerLink) centerLink.textContent = (tt.ui&&tt.ui.fullCenterLink) || 'Full privacy notice & regional legal matrix →';

    // RTL（阿拉伯语/波斯语）
    const isRtl = !!tt.rtl;
    if(bodyEl){ bodyEl.dir = isRtl ? 'rtl' : 'ltr'; bodyEl.style.textAlign = isRtl ? 'right' : 'left'; }
    const modalBox = modal.querySelector('.modalbox');
    if(modalBox) modalBox.dir = isRtl ? 'rtl' : 'ltr';

    // 正文按需从 /legal/privacy.<lang>.html 加载（独立文件，不打进主程序）
    if(bodyEl){
      bodyEl.innerHTML = '<p style="color:#64748b">'+((tt.ui&&tt.ui.loading)||'Loading…')+'</p>';
      if(window.PRIVACY_TEXTS && window.PRIVACY_TEXTS.fetchNotice){
        window.PRIVACY_TEXTS.fetchNotice(tt.lang).then(function(notice){
          if(!modal || modal.style.display==='none') return;
          bodyEl.innerHTML = notice.html;
          bodyEl.dir = isRtl ? 'rtl' : 'ltr';
          // 正文注入后再开始计时，避免加载耗时占用阅读倒计时
          startTime = Date.now();
          if(scrollArea) scrollArea.scrollTop = 0;
          scrolledToBottom = false;
          clearInterval(timer);
          timer = setInterval(function(){
            updateState();
            if(scrolledToBottom && (Date.now() - startTime) >= 5000) clearInterval(timer);
          }, 250);
          setTimeout(function(){
            if(scrollArea && scrollArea.scrollHeight <= scrollArea.clientHeight + 8){
              scrolledToBottom = true;
              if(overlay) overlay.style.opacity='0';
              updateState();
            }
          },150);
          updateState();
        }).catch(function(){
          bodyEl.innerHTML = '<p>'+((tt.ui&&tt.ui.loadFail)||'Could not load the notice.')+'</p>';
        });
      } else {
        bodyEl.innerHTML = tt.body || '';
      }
    }

    startTime = Date.now();

    if(scrollArea) scrollArea.scrollTop = 0;
    if(overlay){ overlay.style.opacity = '1'; overlay.style.display = 'flex'; }
    if(cb) cb.checked = false;
    if(pcb) pcb.checked = false;
    scrolledToBottom = false;
    agreed = false;
    parentAgreed = false;

    modal.classList.add('open');
    modal.style.display = 'flex';

    updateState();

    clearInterval(timer);
    timer = setInterval(function(){
      updateState();
      if(scrolledToBottom && (Date.now() - startTime) >= 5000){
        clearInterval(timer);
      }
    }, 250);

    if(scrollArea){
      scrollArea.onscroll = function(){
        if(overlay){
          if(scrollArea.scrollTop > 10) overlay.style.opacity = '0';
          else overlay.style.opacity = '1';
        }
        const isBottom = scrollArea.scrollHeight - scrollArea.scrollTop <= scrollArea.clientHeight + 15;
        if(isBottom !== scrolledToBottom){
          scrolledToBottom = isBottom;
          updateState();
        }
      };
      setTimeout(function(){
        if(scrollArea.scrollHeight <= scrollArea.clientHeight + 8){
          scrolledToBottom = true;
          if(overlay) overlay.style.opacity = '0';
          updateState();
        }
      }, 120);
    }

    if(cb){
      cb.onchange = function(){
        agreed = cb.checked;
        updateState();
      };
    }
    if(pcb){
      pcb.onchange = function(){
        parentAgreed = pcb.checked;
        updateState();
      };
    }

    if(submitBtn){
      submitBtn.onclick = function(){
        const elapsed = (Date.now() - startTime) / 1000;
        if(!scrolledToBottom || !agreed || !parentAgreed || elapsed < 5) return;
        localStorage.setItem(LS_KEY, '1');
        // 合规留证：两个独立确认动作（已读确认 + 家长/监护人同意）
        try{
          localStorage.setItem(META_KEY, JSON.stringify({
            ack: true, parent_consent: true, lang: tt.lang || (currentLang||'en'),
            at: new Date().toISOString(), v: 'v5.5.3'
          }));
        }catch(e){}
        close(true);
      };
    }
  }

  function close(ok){
    const modal = document.getElementById('privacyModal');
    if(modal){
      modal.classList.remove('open');
      modal.style.display = 'none';
    }
    unlockBackgroundScroll();
    clearInterval(timer);
    // 用户同意后，自动勾选主界面的复选框
    if(ok){
      const mainAgree = document.getElementById('agree');
      if(mainAgree){
        mainAgree.checked = true;
      }
    }
    if(pendingResolve){ pendingResolve(ok); pendingResolve = null; }
  }

  window.CalcElfPrivacy = {
    require: function(){
      if(localStorage.getItem(LS_KEY) === '1') return Promise.resolve(true);
      return new Promise(function(resolve){ pendingResolve = resolve; open(); });
    },
    // 不管之前是否同意过，都强制弹窗（用于用户主动点击“我已阅读”文字或复选框）
    forceOpen: function(){
      return new Promise(function(resolve){ pendingResolve = resolve; open(); });
    },
    isAgreed: function(){ return localStorage.getItem(LS_KEY) === '1'; },
    reset: function(){ localStorage.removeItem(LS_KEY); localStorage.removeItem(META_KEY); }
  };
})();

/* =========================================================
   CalcElf 彩带
   ========================================================= */
(function(){
  let canvas=null, ctx=null, particles=[], raf=null;
  function ensureCanvas(){ if(canvas)return; canvas=document.createElement('canvas'); canvas.id='calcelfConfettiCanvas'; canvas.style.position='fixed'; canvas.style.inset='0'; canvas.style.width='100vw'; canvas.style.height='100vh'; canvas.style.pointerEvents='none'; canvas.style.zIndex='2147483647'; document.body.appendChild(canvas); ctx=canvas.getContext('2d'); resize(); window.addEventListener('resize',resize); }
  function resize(){ if(!canvas)return; const dpr=window.devicePixelRatio||1; canvas.width=window.innerWidth*dpr; canvas.height=window.innerHeight*dpr; ctx.setTransform(dpr,0,0,dpr,0,0); }
  function random(min,max){ return Math.random()*(max-min)+min; }
  function burst(options){ ensureCanvas(); const opt=options||{}; const count=opt.count||120; const duration=opt.duration||2600; const colors=opt.colors||['#ff4d6d','#ffb703','#00d4ff','#7cff6b','#c77dff','#ff8fab','#ffd93d','#4cc9f0']; for(let i=0;i<count;i++){ particles.push({ x:window.innerWidth*random(0.15,0.85), y:window.innerHeight*random(0.1,0.45), vx:random(-7,7), vy:random(-11,-2), size:random(5,13), color:colors[Math.floor(Math.random()*colors.length)], rot:random(0,Math.PI*2), vr:random(-0.25,0.25), life:duration, born:performance.now(), shape:Math.random()>0.5?'rect':'circle' }); } if(!raf)loop(); }
  function loop(){ raf=requestAnimationFrame(loop); ctx.clearRect(0,0,window.innerWidth,window.innerHeight); const now=performance.now(); particles=particles.filter(function(p){ const age=now-p.born; if(age>p.life)return false; p.vy+=0.22; p.vx*=0.992; p.x+=p.vx; p.y+=p.vy; p.rot+=p.vr; ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.rot); ctx.globalAlpha=Math.max(0,1-age/p.life); ctx.fillStyle=p.color; if(p.shape==='circle'){ ctx.beginPath(); ctx.arc(0,0,p.size*0.5,0,Math.PI*2); ctx.fill(); } else { ctx.fillRect(-p.size*0.5,-p.size*0.25,p.size,p.size*0.5); } ctx.restore(); return true; }); if(particles.length===0){ cancelAnimationFrame(raf); raf=null; ctx.clearRect(0,0,window.innerWidth,window.innerHeight); } }
  window.CalcElfConfetti={ burst:burst };
})();

/* =========================================================
   CalcElf 欢迎开箱仪式
   ========================================================= */
(function(){
  const ANIMATION_MAP={
    'party-celebration':{file:'party-celebration.json',duration:3000},
    'happy-smile':{file:'happy-smile.json',duration:3000},
    'gift-box':{file:'gift-box.json',duration:2600},
    'rocket-launch':{file:'rocket-launch.json',duration:2400},
    'thumbs-up':{file:'thumbs-up.json',duration:2400},
    'clapping':{file:'clapping.json',duration:2200},
    'balloon-float':{file:'balloon-float.json',duration:2400},
    'waving':{file:'waving.json',duration:2200},
    'smile-face':{file:'smile-face.json',duration:3000},
    'energy-core':{file:'energy-core.json',duration:3000},
    'key-unlock':{file:'key-unlock.json',duration:3000}
  };
  const STAGE_POOLS={
    primary_1_3:['gift-box','happy-smile','balloon-float','clapping','thumbs-up','waving','smile-face'],
    primary_3_6:['party-celebration','rocket-launch','thumbs-up','gift-box','happy-smile','balloon-float'],
    middle_1_2:['energy-core','rocket-launch','party-celebration','thumbs-up'],
    grade_9_12:['key-unlock','energy-core','rocket-launch','party-celebration'],
    prefer_not:['party-celebration','gift-box','rocket-launch','happy-smile','balloon-float']
  };
  let currentAnim=null, currentRoot=null, closeTimer=null;
  function pickNext(stage){ const pool=STAGE_POOLS[stage]||STAGE_POOLS.prefer_not; const key='calcelf_welcome_last_'+stage; let last=parseInt(localStorage.getItem(key)||'-1',10); let next=(last+1)%pool.length; localStorage.setItem(key,String(next)); return pool[next]; }
  function ensureRoot(){ if(currentRoot)return currentRoot; const root=document.createElement('div'); root.id='calcelfWelcomeRoot'; root.className='calcelf-welcome-root'; root.style.display='none'; root.innerHTML=`<div class="calcelf-welcome-stage"><div id="calcelfLottieBox" class="calcelf-lottie-box"></div><div class="calcelf-welcome-content"><h2 id="calcelfWelcomeTitle">Welcome to CalcElf!</h2><p id="calcelfWelcomeDesc">Your 100 Credits are ready!</p><button id="calcelfWelcomeBtn" class="btn primary">Start my journey</button></div></div>`; document.body.appendChild(root); root.querySelector('#calcelfWelcomeBtn').addEventListener('click',function(){ close(); }); currentRoot=root; return root; }
  function showContent(credits){ const root=ensureRoot(); const desc=root.querySelector('#calcelfWelcomeDesc'); if(credits)desc.textContent='Your '+credits+' Credits are ready!'; root.classList.add('show-content'); if(window.CalcElfConfetti)window.CalcElfConfetti.burst({count:180,duration:3200}); }
  function trigger(options){ const opt=options||{}; const stage=opt.stage||'prefer_not'; const credits=opt.credits||100; const chosen=pickNext(stage); const item=ANIMATION_MAP[chosen]||ANIMATION_MAP['party-celebration']; const root=ensureRoot(); root.style.display='flex'; root.classList.remove('show-content'); const box=root.querySelector('#calcelfLottieBox'); box.innerHTML=''; if(currentAnim){ try{currentAnim.destroy();}catch(e){} currentAnim=null; } if(!window.lottie){ setTimeout(function(){ showContent(credits); },300); return; } currentAnim=window.lottie.loadAnimation({ container:box, renderer:'svg', loop:true, autoplay:true, path:'/animations/'+item.file, rendererSettings:{ preserveAspectRatio:'xMidYMid slice', progressiveLoad:true } }); clearTimeout(closeTimer); closeTimer=setTimeout(function(){ if(currentAnim){ try{currentAnim.destroy();}catch(e){} currentAnim=null; } showContent(credits); }, item.duration||2800); }
  function close(){ const root=ensureRoot(); root.style.display='none'; root.classList.remove('show-content'); if(currentAnim){ try{currentAnim.destroy();}catch(e){} currentAnim=null; } if(window.CalcElfConfetti)window.CalcElfConfetti.burst({count:120,duration:2600}); }
  window.CalcElfWelcome={ trigger:trigger, close:close, pools:STAGE_POOLS, animations:ANIMATION_MAP };
})();

// ====== 隐私拦截辅助函数：先看主界面勾选框，再看 localStorage ======
async function calcelfEnsurePrivacy(){
  const mainAgree = document.getElementById('agree');
  if(mainAgree && mainAgree.checked){
    try{ localStorage.setItem('calcelf_privacy_agreed_v1', '1'); }catch(e){}
    return true;
  }
  if(!window.CalcElfPrivacy) return true;
  if(window.CalcElfPrivacy.isAgreed()) return true;
  return await window.CalcElfPrivacy.require();
}

function creditTier(total,grant,plan){
  const n=Math.max(0,Number(total)||0), b=Math.max(0,Number(grant)||0);
  if(plan==='free'||b<=50){ const ratio=n/Math.max(b,20); return ratio>.50?4:ratio>.25?3:ratio>.10?2:1; }
  return n>=500?4:n>=100?3:n>=20?2:1;
}
function creditUi(){return CREDIT_METER_UI[currentLang]||CREDIT_METER_UI.en}
function renderCreditMeter(total,isAdult,grant,plan,profile){
  const d=creditUi(), w=$('creditMeterWidget'); if(!w)return;
  const n=Math.max(0,Number(total)||0), tier=creditTier(n,grant,plan), role='child';
  w.className='ce-credit-widget role-'+role+' tier-'+tier;
  setText('credits',n);setText('creditsLabel',t('creditsLabel')||'Credits');setText('planPill',plan||'free');
  const status=[null,d.c,d.l,d.s,d.p][tier];setText('creditStatusLabel',status||d.p);$('creditStatusLabel')?.setAttribute('class','ce-status-pill tier-'+tier);
  setText('creditSubline',(role==='child'?d.child:d.adult)[4-tier]||'');
  setText('creditActionBtn',role==='child'?d.childBtn:d.adultBtn);setText('creditTierLeft',d.left);setText('creditTierRight',d.right);
  const rail=$('creditTierRail');if(rail)rail.querySelectorAll('.ce-tier-dot').forEach((x,i)=>x.classList.toggle('active',i===tier-1));
  const notice=$('creditNotice');let msg='';
  if(role==='child'&&tier===2)msg=d.low;else if(role==='child'&&tier===1)msg=d.crit;else if(role==='adult'&&tier===2)msg=d.alow;else if(role==='adult'&&tier===1)msg=d.acrit;
  if(notice){notice.innerHTML=msg?'<span class="ce-notice-icon">'+(role==='child'?'💧':'!')+'</span><span>'+esc(msg)+'</span>':'';notice.className='ce-credit-notice tier-'+tier+(msg?' show':'');}
  const care=$('careResetBtn'),month=new Date().toISOString().slice(0,7), used=profile?.loyalty_reset_used_month;
  if(care)care.style.display=(plan!=='free'&&n<=0&&used!==month)?'inline-flex':'none';
  document.body.dataset.accountRole=profile?.account_role||'parent';
}
function calcelfUpdateCreditMeter(total,isAdult,grant,plan,profile){renderCreditMeter(total,isAdult,grant,plan,profile)}

