function renderMembershipCard(profile){
  if(!profile)return;
  const d=creditUi(),m=Math.min(6,Math.max(1,Number(profile.monthly_level)||1)),l=Math.min(7,Math.max(1,Number(profile.lifetime_level)||1));
  const solved=Number(profile.monthly_solved)||0,correct=Number(profile.lifetime_correct)||0,mt=[10,30,60,100,101,101],lt=[50,200,500,1000,2500,5000,5001];
  const pm=m===1?0:mt[m-2],pl=l===1?0:lt[l-2],mp=m>=6?100:Math.min(100,Math.max(0,(solved-pm)/Math.max(1,mt[m-1]-pm)*100)),lp=l>=7?100:Math.min(100,Math.max(0,(correct-pl)/Math.max(1,lt[l-1]-pl)*100));
  setText('membershipEyebrow',d.me);setText('membershipTitle',d.mt);setText('membershipPlan',profile.plan||'free');
  setText('membershipRole',profile.account_role==='parent'?d.parent:profile.account_role==='adult'?d.adultRole:d.learner);setText('membershipLevelName',d.ln[l-1]||('Level '+l));setText('membershipPerk',d.perk[Math.min(d.perk.length-1,m-1)]||'');
  setText('monthlyLevelTitle',d.month);setText('lifetimeLevelTitle',d.life);setText('monthlyLevelValue',m);setText('lifetimeLevelValue',l);setText('monthlyLevelName',d.mn[m-1]||('Level '+m));setText('lifetimeLevelName',d.ln[l-1]||('Level '+l));setText('monthlyProgressText',d.pm.replace('{n}',solved));setText('lifetimeProgressText',d.pl.replace('{n}',correct));setText('membershipThemeHint',d.hint);setText('membershipBtn',d.view);
  const a=$('membershipAvatar');if(a){a.innerHTML=LEVEL_ICONS[l-1]||LEVEL_ICONS[0];a.className='ce-member-avatar life-'+l+' monthly-'+m}
  const x=$('monthlyProgress'),y=$('lifetimeProgress');if(x)x.style.width=mp+'%';if(y)y.style.width=lp+'%';
}
