function calcelfRenderAvatar(profile){
  const avatarEl=document.getElementById('profileAvatarDisplay'); if(!avatarEl)return;
  const ZK=['rat','ox','tiger','rabbit','dragon','snake','horse','goat','monkey','rooster','dog','pig'];
  const raw=profile?.avatar;
  const avatarHtml=ZK.includes(raw)?'<img src="/avatars/zodiac/'+raw+'.svg" style="width:56px;height:56px;border-radius:50%;background:#fff;object-fit:cover">':('<span style="font-size:44px;line-height:1;">'+(raw||'🦊')+'</span>');
  const ml=profile?.monthly_level||1, ll=profile?.lifetime_level||1;
  let crownClass='crown-bronze'; if(ml>=5)crownClass='crown-gold'; else if(ml>=3)crownClass='crown-silver';
  let scarfClass='scarf-blue'; if(ll>=7)scarfClass='scarf-rainbow'; else if(ll>=5)scarfClass='scarf-purple'; else if(ll>=3)scarfClass='scarf-green';
  avatarEl.innerHTML=`<span class="avatar-crown ${crownClass}">👑</span>${avatarHtml}<span class="avatar-scarf ${scarfClass}">🧣</span>`;
}

async function auth(){
  const s = await session();
  if (s && s.user?.is_anonymous) {
    const ANON_UP={'zh-CN':'您当前是免费体验模式。注册账号可保留解题记录，并解锁动画功能！\n\n点击“确定”立即注册。','zh-TW':'您目前是免費體驗模式。註冊帳號可保留解題紀錄，並解鎖動畫功能！\n\n點擊「確定」立即註冊。',en:'You are in free guest mode. Create a free account to save your work and unlock animations!\n\nPress OK to sign up.',fr:'Vous êtes en mode invité gratuit. Créez un compte gratuit pour sauvegarder votre travail et débloquer les animations !\n\nOK pour vous inscrire.',de:'Du nutzt den kostenlosen Gastmodus. Erstelle ein Gratis-Konto, um deinen Fortschritt zu speichern und Animationen freizuschalten!\n\nFür die Anmeldung auf OK.',es:'Estás en modo invitado gratuito. Crea una cuenta gratis para guardar tu progreso y desbloquear animaciones.\n\nPulsa Aceptar para registrarte.',it:'Sei in modalità ospite gratuita. Crea un account gratuito per salvare i progressi e sbloccare le animazioni!\n\nPremi OK per registrarti.',ja:'無料ゲストモードです。無料アカウントを作ると学習記録が保存され、アニメーションが解放されます！\n\nOKで登録へ。',ko:'무료 체험 모드입니다. 무료 계정을 만들면 학습 기록이 저장되고 애니메이션이 열립니다!\n\n확인을 눌러 가입하세요.',ar:'أنت في وضع الضيف المجاني. أنشئ حسابًا مجانيًا لحفظ عملك وفتح الرسوم المتحركة!\n\nاضغط موافق للتسجيل.',fa:'در حالت مهمان رایگان هستید. یک حساب رایگان بسازید تا کارتان ذخیره و انیمیشن‌ها باز شوند!\n\nبرای ثبت‌نام تأیید را بزنید.'};
    const upgrade = confirm(ANON_UP[currentLang]||ANON_UP.en);
    if (upgrade) openModal('authModal');
    return;
  }
  if(!s && sb) { try { await sb.auth.signInAnonymously(); } catch(e) { console.log('Anonymous login failed:', e); } }
  openModal('authModal');
}
function showLoginTab(){ const lf = $('loginForm'), sf = $('signupForm'); if(lf) lf.style.display = 'block'; if(sf) sf.style.display = 'none'; if($('tabLogin')) $('tabLogin').classList.add('active'); if($('tabSignup')) $('tabSignup').classList.remove('active'); }
function showSignupTab(){ const lf = $('loginForm'), sf = $('signupForm'); if(lf) lf.style.display = 'none'; if(sf) sf.style.display = 'block'; if($('tabSignup')) $('tabSignup').classList.add('active'); if($('tabLogin')) $('tabLogin').classList.remove('active'); }
async function loginWithPassword(){
  if(!(await calcelfEnsurePrivacy())) return;
  const email = $('loginEmail').value.trim(); const password = $('loginPassword').value;
  if(!email || !password) { setText('authMsg', 'Please fill in email and password'); return; }
  const { error } = await sb.auth.signInWithPassword({ email, password });
  if(error) { setText('authMsg', error.message); return; }
  setText('authMsg', 'Login successful!'); $('authModal').classList.remove('open'); await refresh();
}
