async function signupWithPassword(){
  if(!(await calcelfEnsurePrivacy())) return;
  const consent=window.__calfSignupConsent;
  if(!consent||!consent.privacy||!consent.coppa){setText('authMsg',SIGNUP_GUARD_MSG[currentLang]||SIGNUP_GUARD_MSG.en);return;}
  const email = $('signupEmail').value.trim(); const password = $('signupPassword').value; const name = $('signupName').value.trim(); const role = $('signupRole').value;
  if(!email || !password) { setText('authMsg', 'Please fill in email and password'); return; }
  if(password.length < 8) { setText('authMsg', 'Password must be at least 8 characters'); return; }
  const { error } = await sb.auth.signUp({ email, password, options: { data: { display_name: name, account_role: role, consent_privacy:true, consent_coppa:true, consent_at:consent.at }, emailRedirectTo: location.origin } });
  if(error) { setText('authMsg', error.message); return; }
  // v5.6.5：注册成功后弹“去邮箱确认”，确定后关闭注册窗、保持未登录
  try{ ['signupEmail','signupPassword','signupName'].forEach(id=>{const e=$(id);if(e)e.value='';}); setText('authMsg',''); }catch(_){}
  openVerifyModal();
}
