// v5.10 备注/关注点分类：含问号/疑问词 → 独立疑问（解题后走聊天）；否则视为补充条件（融入解题）
function classifyNote(text){
  if(!text||!text.trim()) return {text:'', questions:[]};
  const lines=text.split(/\n+/).map(s=>s.trim()).filter(Boolean);
  const qRe=/[?？¿؟]|为什么|為什麼|为何|為何|怎么|怎麼|怎样|怎樣|如何|吗|嗎|呢|怎么来|為何|why|how\b|what\b|come (?:si|fa|fare|mai)|comment\b|pourquoi|warum|كيف|لماذا|چطور|چرا/;
  const questions=[], keep=[];
  lines.forEach(line=>{ (qRe.test(line)?questions:keep).push(line); });
  return { text:keep.join('\n'), questions };
}
