// ============================================================
// 动画模式开关（改这一行即可切换）：
//  'hybrid' = 混合：常见题型走确定性分镜，没命中再让模型自由写整页（推荐）
//  'free'   = 完全开放：直接让模型（默认 DeepSeek）自由写一整页 HTML
//  'plan'   = 仅确定性分镜：只用固定渲染器，失败出静态步骤卡
// ============================================================
// v5.8.4：独立动画个体——只调 /api/animation，把题目原文直接交给动画模型，
// 由模型自己解题并返回一整页 HTML；不再先调规划器（planner 代码保留但不调用）。
const ANIMATION_MODE = 'free';
async function animation(isGrace = false, attempt = 0){
  const s=await session();if(!s)return;
  const u=animUi();
  const animCard=$('animCard'); if(animCard) animCard.style.display='';
  $('animBox').style.display='block'; $('animBox').classList.add('anim-busy');
  $('animBox').innerHTML=`<div class="anim-loading">
     <div class="anim-stage">
       ${window.calfAnimWizard?calfAnimWizard():'<img src="/calcelf-logo.png" class="anim-mascot" alt="">'}
       <div class="anim-ring-wrap"><div class="anim-ring"></div><span class="ring-star">${window.calfIcon?calfIcon('starFill'):'★'}</span></div>
     </div>
     <div class="anim-msg">${esc(u.title)}</div>
     <div class="anim-sub">${esc(u.sub)}</div>
     <div class="anim-dots"><i></i><i></i><i></i></div>
   </div>`;
  const body={ problem:currentResult.question_text, solutions:currentResult.solutions, language:currentLang, stage:$('stage').value, is_grace:isGrace };
  // v6.0：kard 优先动画流程追踪
  let animSource='none';
  let kardEligible=false;
  let kardFamily=null;

  function showAnon(){
    $('animBox').classList.remove('anim-busy');
    $('animBox').innerHTML = `<div style="padding:35px;text-align:center;background:#2a1f16;border-radius:12px; border:1px dashed #ffb06b;"><img src="/calcelf-logo.png" style="width:60px; height:60px; margin-bottom:10px; animation: bounce 1.5s infinite ease-in-out;"><div style="font-size:15px; font-weight:800; color:#ffd9b0; line-height:1.6;">${esc(u.signup)}</div></div>`;
  }
  async function post(url,waitMs){
    const ctrl=new AbortController(); const t=setTimeout(()=>ctrl.abort(),waitMs);
    try{
      const r=await fetch(url,{ method:'POST', headers:authHeader(s), signal:ctrl.signal, body:JSON.stringify(body) });
      clearTimeout(t);
      const j=await r.json().catch(()=>({}));
      if(!r.ok){
        if(r.status===403 && j.code==='ANON_ANIMATION_BLOCKED') return {anon:true};
        throw Error(j.code==='RATE_LIMITED' ? u.slow : u.failed);
      }
      if(typeof j.credits==='number') setText('credits',j.credits);
      return {j};
    }catch(e){ clearTimeout(t); throw e; }
  }
  // v3.4 具象质量门：只接受含真正图形/动画场景的规划结果，adaptive 文字步骤列表不算
  const CALF_CONCRETE_VISUAL=['eq','bar','barstep','layers','compare','diagram','motion','wellclimb','world','geometry','force','circuit','molecule','process'];
  function planConcrete(plan){
    return !!(plan && Array.isArray(plan.scenes) &&
      plan.scenes.some(s=>s && CALF_CONCRETE_VISUAL.includes(s.t)));
  }
  function planDoc(j){
    if(j && j.eligible && j.plan && planConcrete(j.plan) && window.CalcElfAnimPlayer){
      try{ return window.CalcElfAnimPlayer.build(j.plan,currentLang); }catch(e){ console.error('player build failed',e); }
    }
    return '';
  }
  function present(doc){
    $('animBox').classList.remove('anim-busy'); $('animBox').innerHTML='';
    const f=document.createElement('iframe'); f.className='calfAnimFrame'; f.sandbox='allow-scripts'; f.srcdoc=doc;
    $('animBox').appendChild(f);
    const fsBtn=$('animFs');
    if(fsBtn){ fsBtn.style.display='inline-flex'; fsBtn.innerHTML=(window.calfIcon?calfIcon('expand'):'⛶')+' '+esc(u.fs); fsBtn.onclick=()=>openAnimFullscreen(doc); }
  }
  function presentStatic(){
    $('animBox').classList.remove('anim-busy');
    $('animBox').innerHTML=staticStepsHtml();
    const fsBtn=$('animFs'); if(fsBtn) fsBtn.style.display='none';
  }

  // v6.0：kard 优先探测（10s 超时，失败静默走兜底链）
  try{
    const kardCtrl=new AbortController();
    const kardTimer=setTimeout(()=>kardCtrl.abort(),10000);
    const kr=await fetch('/api/kard',{method:'POST',headers:authHeader(s),signal:kardCtrl.signal,body:JSON.stringify({problem:currentResult.question_text,text:currentResult.question_text,language:currentLang,stage:$('stage').value})});
    clearTimeout(kardTimer);
    const kj=await kr.json().catch(()=>({}));
    if(kj && kj.eligible){
      kardEligible=true;
      kardFamily=kj.family||null;
      animSource='kard';
      // v6.1：board 族 host 选择器。host 缺失或 'renderer' → 走原 renderer 流程（向后兼容）；
      // host 为 '2d'|'3d'|'reaction'|'solid' → 走 /board/{host}.html 板播放器。
      const host=kj.host||'renderer';
      if(host==='renderer'){
        presentKard(kj.renderParams);
      }else{
        presentBoard(host,{board:kj.board,lesson:kj.lesson,steps:kj.steps,answer:kj.answer});
      }
      showRatingWidget('kard',kardFamily,currentResult.question_text);
      logAnimationFlow(animSource,kardEligible,kardFamily);
      return;
    }
    if(kj && kj.family) kardFamily=kj.family;
  }catch(e){ console.warn('kard probe failed',e); }

  try{
    let doc='';
    if(ANIMATION_MODE==='plan'){
      const p=await post('/api/animation-plan',30000);
      if(p.anon){ showAnon(); return; }
      doc=planDoc(p.j);
      if(doc) animSource='plan';
    }else if(ANIMATION_MODE==='free'){
      const f=await post('/api/animation',60000);
      if(f.anon){ showAnon(); return; }
      doc=(f.j && f.j.eligible && f.j.html)||'';
      if(doc) animSource='free';
      if(!doc){
        // v5.9：free 失败 → 固定播放器（具象分镜）兜底，仍不行才出静态步骤卡，保证永不白屏
        try{
          const p=await post('/api/animation-plan',30000);
          if(p.anon){ showAnon(); return; }
          doc=planDoc(p.j);
          if(doc) animSource='plan';
        }catch(e){ console.warn('animation-plan fallback failed',e); }
      }
    }else{ // hybrid
      const p=await post('/api/animation-plan',30000);
      if(p.anon){ showAnon(); return; }
      doc=planDoc(p.j);
      if(doc) animSource='plan';
      if(!doc){
        const f=await post('/api/animation',55000);
        if(f.anon){ showAnon(); return; }
        doc=(f.j && f.j.eligible && f.j.html)||'';
        if(doc) animSource='free';
      }
    }
    if(doc){ present(doc); showRatingWidget(animSource,kardFamily,currentResult.question_text); }
    else { presentStatic(); animSource='static'; }
  } catch (e){
    console.error('Animation Error:', e); const x=animUi();
    const netFail=(e&&(e.name==='AbortError'||/failed to fetch|network|load failed|aborted|timeout/i.test(e.message||'')));
    if(netFail && attempt===0){
      $('animBox').classList.add('anim-busy');
      $('animBox').querySelectorAll('.anim-sub').forEach(n=>n.textContent=x.retry||'');
      setTimeout(()=>{ try{animation(isGrace,1);}catch(_){} },1600);
      return;
    }
    const msg=(e&&e.name==='AbortError')?x.timeout:(e.message||x.failed);
    $('animBox').classList.remove('anim-busy');
    $('animBox').innerHTML=`<div class="anim-loading"><div style="font-size:40px">${window.calfIcon?calfIcon('film'):'🎬'}</div>
      <div class="anim-sub" style="color:#b45309">${esc(msg)}</div>
      <button class="btn primary anim-retry" id="animRetry">${(window.calfIcon?calfIcon('retry'):'')+' '+esc(x.retry)}</button></div>`;
    const rb=$('animRetry'); if(rb) rb.onclick=()=>animation(isGrace,0);
  } finally {
    logAnimationFlow(animSource,kardEligible,kardFamily);
  }
}
function openAnimFullscreen(doc){
  let ov=document.getElementById('animFsOverlay');
  if(!ov){ov=document.createElement('div');ov.id='animFsOverlay';document.body.appendChild(ov);}
  ov.innerHTML='<div class="animFsBox"><button id="animFsClose" class="btn primary" style="position:fixed;top:14px;right:18px;z-index:10001">✕</button><iframe class="calfAnimFrame fs"></iframe></div>';
  ov.querySelector('iframe').srcdoc=doc;
  ov.classList.add('open');
  ov.querySelector('#animFsClose').onclick=()=>ov.classList.remove('open');
  ov.onclick=(e)=>{if(e.target===ov)ov.classList.remove('open');};
}
window.addEventListener('message',(ev)=>{
  const h=ev.data&&ev.data.__calfAnimHeight;
  if(typeof h==='number'&&h>120){const minH=window.innerWidth<640?420:620;document.querySelectorAll('iframe.calfAnimFrame:not(.fs)').forEach(f=>{f.style.height=Math.min(Math.max(h,minH),1100)+'px';});}
});

// v6.0：kard 渲染器挂载（/renderer/index.html，postMessage 传入 renderParams）
function presentKard(renderParams){
  $('animBox').classList.remove('anim-busy');
  $('animBox').innerHTML='';
  const f=document.createElement('iframe');
  f.className='calfAnimFrame kard-frame';
  f.sandbox='allow-scripts allow-same-origin';
  f.src='/renderer/index.html';
  f.style.width='100%';
  f.style.border='none';
  f.style.borderRadius='16px';
  f.style.background='#0d1228';
  f.style.minHeight=(window.innerWidth<640?'420px':'620px');
  f.onload=()=>{ try{ f.contentWindow.postMessage({animation:renderParams},'*'); }catch(e){} };
  $('animBox').appendChild(f);
  const fsBtn=$('animFs');
  if(fsBtn){ fsBtn.style.display='inline-flex'; fsBtn.innerHTML=(window.calfIcon?calfIcon('expand'):'⛶')+' '+esc(animUi().fs); fsBtn.onclick=()=>openKardFullscreen(renderParams); }
}
function openKardFullscreen(renderParams){
  let ov=document.getElementById('animFsOverlay');
  if(!ov){ov=document.createElement('div');ov.id='animFsOverlay';document.body.appendChild(ov);}
  ov.innerHTML='<div class="animFsBox"><button id="animFsClose" class="btn primary" style="position:fixed;top:14px;right:18px;z-index:10001">✕</button><iframe class="calfAnimFrame fs kard-frame" style="width:100%;height:100%;border:none;background:#0d1228"></iframe></div>';
  const ifr=ov.querySelector('iframe');
  ifr.sandbox='allow-scripts allow-same-origin';
  ifr.src='/renderer/index.html';
  ifr.onload=()=>{ try{ ifr.contentWindow.postMessage({animation:renderParams},'*'); }catch(e){} };
  ov.classList.add('open');
  ov.querySelector('#animFsClose').onclick=()=>ov.classList.remove('open');
  ov.onclick=(e)=>{if(e.target===ov)ov.classList.remove('open');};
}

// v6.1：board 族板播放器挂载（/board/{host}.html，postMessage 传入 board/lesson/steps）
// host: '2d'|'3d'|'reaction'|'solid'；payload: {board, lesson?, steps?, answer?}
function presentBoard(host,payload){
  payload=payload||{};
  $('animBox').classList.remove('anim-busy');
  $('animBox').innerHTML='';
  const f=document.createElement('iframe');
  f.className='calfAnimFrame board-frame';
  f.sandbox='allow-scripts allow-same-origin';
  f.src='/board/'+host+'.html';
  f.style.width='100%';
  f.style.border='none';
  f.style.borderRadius='16px';
  f.style.background= host==='3d' ? '#0f172a' : '#f8fafc';
  f.style.minHeight=(window.innerWidth<640?'480px':'680px');
  f.onload=()=>{
    try{
      const msg={
        board: payload.board || {},
        lesson: payload.lesson || {title:'', problem:''},
        steps: payload.steps || []
      };
      // 3d 模板用 board3d 字段名，做兼容
      if(host==='3d') msg.board3d = payload.board || {};
      f.contentWindow.postMessage(msg,'*');
    }catch(e){ console.warn('board postMessage failed', e); }
  };
  $('animBox').appendChild(f);
  const fsBtn=$('animFs');
  if(fsBtn){ fsBtn.style.display='inline-flex'; fsBtn.innerHTML=(window.calfIcon?calfIcon('expand'):'⛶')+' '+esc(animUi().fs); fsBtn.onclick=()=>openBoardFullscreen(host,payload); }
}
function openBoardFullscreen(host,payload){
  payload=payload||{};
  let ov=document.getElementById('animFsOverlay');
  if(!ov){ov=document.createElement('div');ov.id='animFsOverlay';document.body.appendChild(ov);}
  const bg=host==='3d'?'#0f172a':'#f8fafc';
  ov.innerHTML='<div class="animFsBox"><button id="animFsClose" class="btn primary" style="position:fixed;top:14px;right:18px;z-index:10001">✕</button><iframe class="calfAnimFrame fs board-frame" style="width:100%;height:100%;border:none;background:'+bg+'"></iframe></div>';
  const ifr=ov.querySelector('iframe');
  ifr.sandbox='allow-scripts allow-same-origin';
  ifr.src='/board/'+host+'.html';
  ifr.onload=()=>{
    try{
      const msg={
        board: payload.board || {},
        lesson: payload.lesson || {title:'', problem:''},
        steps: payload.steps || []
      };
      if(host==='3d') msg.board3d = payload.board || {};
      ifr.contentWindow.postMessage(msg,'*');
    }catch(e){ console.warn('board fs postMessage failed', e); }
  };
  ov.classList.add('open');
  ov.querySelector('#animFsClose').onclick=()=>ov.classList.remove('open');
  ov.onclick=(e)=>{if(e.target===ov)ov.classList.remove('open');};
}
