// v6.0：动画 5 星评分（kard/free/plan 成功后显示，static 不显示）
function showRatingWidget(source,family,problemText){
  const box=$('animBox'); if(!box) return;
  const old=box.querySelector('.anim-rating'); if(old) old.remove();
  let did=localStorage.getItem('calf_device_id');
  if(!did){ did='dev_'+Math.random().toString(36).slice(2)+Date.now().toString(36); try{localStorage.setItem('calf_device_id',did);}catch(e){} }
  const ui=ratingUi();
  const wrap=document.createElement('div');
  wrap.className='anim-rating';
  wrap.innerHTML='<div class="rating-label">'+esc(ui.prompt)+'</div><div class="rating-stars"></div><div class="rating-thanks" style="display:none"></div>';
  const starsEl=wrap.querySelector('.rating-stars');
  const thanksEl=wrap.querySelector('.rating-thanks');
  for(let i=1;i<=5;i++){
    const s=document.createElement('span');
    s.className='star'; s.textContent='☆'; s.dataset.v=i;
    starsEl.appendChild(s);
  }
  const stars=[...starsEl.querySelectorAll('.star')];
  let locked=false, edits=0, current=0;
  function paint(n){ stars.forEach((st,i)=>{ st.classList.toggle('active', i<n); st.textContent = i<n ? '★' : '☆'; }); }
  function submitRating(v){
    session().then(s=>{
      fetch('/api/rate-animation',{method:'POST',headers:s?authHeader(s):{'Content-Type':'application/json'},body:JSON.stringify({rating:v,problem_text:problemText,family:family,source:source,device_id:did})}).catch(()=>{});
    }).catch(()=>{});
  }
  stars.forEach(st=>{
    st.addEventListener('mouseenter',()=>{ if(!locked) paint(+st.dataset.v); });
    st.addEventListener('click',()=>{
      if(locked) return;
      const v=+st.dataset.v; current=v; paint(v);
      thanksEl.style.display='';
      thanksEl.textContent=ui.thanks+' ';
      if(edits===0){
        const chg=document.createElement('span'); chg.className='rating-change'; chg.textContent=ui.change;
        thanksEl.appendChild(chg);
        chg.onclick=()=>{ edits++; locked=false; thanksEl.style.display='none'; paint(0); };
      }
      locked=true;
      submitRating(v);
    });
  });
  starsEl.addEventListener('mouseleave',()=>{ if(!locked) paint(current); });
  box.appendChild(wrap);
}


