function extraUi(){return Object.assign({},EXTRA_UI.en,EXTRA_UI[currentLang]||{});}
window.__practiceUnlocked=1;
function practiceLockKey(level){return 'practice_lock_lvl'+level;}
function readPracticeLock(level){ try{ const raw=localStorage.getItem(practiceLockKey(level)); return raw?JSON.parse(raw):null; }catch(e){ return null; } }
function renderPracticeLevels(){
  const u=window.__practiceUnlocked||1;
  const map=[['practice1',1],['practice2',2],['practice3',3]];
  map.forEach(([id,lv])=>{const b=$(id);if(!b)return;b.classList.remove('lvl-done','lvl-open','lvl-lock');b.classList.remove('lvl-finger');
    const label=(window.calfStripEmoji?calfStripEmoji(b.textContent):b.textContent).replace(/🔒/g,'').replace(/👇/g,'').trim()||('Level '+lv);
    const lock=readPracticeLock(lv);
    if(lock){ b.classList.add('lvl-done'); b.innerHTML=label+(lock.correct?' ✅':' ✔'); }
    else if(lv<u){b.classList.add('lvl-done');b.innerHTML=label;}
    else if(lv===u){b.classList.add('lvl-open','lvl-finger');b.innerHTML=label+' 👇';}
    else {b.classList.add('lvl-lock');b.innerHTML=label+' '+(window.calfIcon?calfIcon('lock','ic-lock'):'🔒');}
  });
}
function renderLockedPractice(level, lock){
  const eu=extraUi();
  $('practiceArea').innerHTML=`<div class="card" style="margin-top:8px"><div class="question" style="font-weight:700">${esc(lock.problemText||'')}</div><div style="margin:8px 0;color:#16a34a;font-weight:800;font-size:13.5px">🔒 ${esc(eu.lockedStored)}</div><div id="gradeFeedback">${lock.feedbackHtml||''}</div></div>`;
}
async function practice(level){
  const s=await session();if(!s){openModal('authModal');return}
  if(!currentResult)return;
  const u=pui();
  if(level>(window.__practiceUnlocked||1)){toast(u.locked);return}
  // v5.10 已答过 → 直接恢复锁定结果，不重新生成、不重新扣费
  const existing=readPracticeLock(level);
  if(existing&&existing.locked){ renderLockedPractice(level, existing); return; }
  const r=await fetch('/api/practice',{method:'POST',headers:authHeader(s),body:JSON.stringify({level,problem:currentResult.question_text,language:currentLang})}),j=await r.json();
  if(!r.ok){toast(j.error||t('genericError'));return}
  setText('credits',j.credits);
  $('practiceArea').innerHTML=`<div class="card" style="margin-top:8px"><div class="question" style="font-weight:700">${esc(j.practice.problem_text)}</div><textarea id="practiceAnswer" rows="3" placeholder="${esc(t('practiceAnswer'))}"></textarea><button class="btn primary" id="gradeBtn" style="margin-top:10px">${esc(t('check'))}</button><div id="gradeFeedback"></div></div>`;
  $('gradeBtn').onclick=async()=>{
    const ans=$('practiceAnswer').value.trim(); if(!ans){toast(t('practiceAnswer'));return;}
    $('gradeBtn').disabled=true;
    const rr=await fetch('/api/grade',{method:'POST',headers:authHeader(s),body:JSON.stringify({practiceId:j.practice.id,answer:ans,language:currentLang})}),jj=await rr.json();
    if(!rr.ok){$('gradeBtn').disabled=false;toast(jj.error||t('genericError'));return}
    const ui=pui(),ok=!!jj.correct;
    const I=window.calfIcon?calfIcon.bind(window):()=>'';
    const face=ok?I('smile'):'🙂'; const faceBad=I('sad')||'🙁';
    const nStars=ok?Math.min(3,Math.max(1,Number(jj.level)||Number(jj.stars)||1)):0;
    const stars=ok?`<span class="grade-stars">${I('starFill').repeat(nStars)||'⭐'.repeat(nStars)}</span>`:'';
    const steps=(jj.solution_steps||[]).filter(Boolean).map((x,k)=>`<li data-n="${k+1}">${esc(x)}</li>`).join('');
    const fbHtml=`<div class="grade-card ${ok?'ok':'bad'}">
      <div class="grade-head">${ok?face:faceBad} <span>${esc(ok?ui.correct:ui.wrong)}</span>${stars}</div>
      <div class="grade-answer">${I('flag')||'🏁'} <span><b>${esc(ui.answer)}:</b> ${esc(jj.answer||'')}</span></div>
      ${steps?`<div class="grade-steps-title">${I('brain')||'🧠'} <span>${esc(ui.solution)}</span></div><ul class="grade-steps">${steps}</ul>`:''}
      ${jj.feedback?`<div style="font-size:14.5px;margin-top:8px;opacity:.85">${esc(jj.feedback)}</div>`:''}
    </div>`;
    $('gradeFeedback').innerHTML=fbHtml;
    // v5.10 首次提交即锁定：锁死输入框、隐藏按钮、持久化（星星仅结算一次）
    const ta=$('practiceAnswer'); if(ta)ta.disabled=true;
    const gb=$('gradeBtn'); if(gb){gb.disabled=true;gb.style.opacity='.55';gb.textContent=ok?'✓ '+t('done'):t('check');}
    const lock={locked:true,correct:ok,stars:nStars,problemText:j.practice.problem_text,feedbackHtml:fbHtml,ts:Date.now()};
    try{ localStorage.setItem(practiceLockKey(level), JSON.stringify(lock)); if(j.practice.id) localStorage.setItem('practice_lock_'+j.practice.id, JSON.stringify(lock)); }catch(e){}
    if(ok){window.__practiceUnlocked=Math.max(window.__practiceUnlocked||1,Math.min(3,level+1));renderPracticeLevels();refresh();}
  }
}
