/* =========================================================
   主界面隐私行行为
   - 匿名用户：点复选框 或 点文字，都弹出隐私弹窗（不直接打勾）
   - 已同意过：复选框可自由切换
   - 弹窗确认后：#agree 自动打勾
   ========================================================= */
(function(){
  const LS_KEY = 'calcelf_privacy_agreed_v1';
  const mainAgree = document.getElementById('agree');
  const privacyLine = document.getElementById('privacyLine');

  // 初始化：如果之前同意过，自动勾上
  if(mainAgree){
    try{ if(localStorage.getItem(LS_KEY) === '1') mainAgree.checked = true; }catch(e){}
  }

  // 点击复选框本体
  if(mainAgree){
    mainAgree.addEventListener('click', function(e){
      // 已同意过 → 允许自由切换
      if(localStorage.getItem(LS_KEY) === '1'){
        if(mainAgree.checked){
          // 用户取消勾选 → 清除记录
          try{ localStorage.removeItem(LS_KEY); }catch(err){}
        } else {
          // 用户重新勾选 → 记回同意
          try{ localStorage.setItem(LS_KEY, '1'); }catch(err){}
        }
        return;
      }
      // 未同意过 → 撤销勾选动作，弹窗让用户阅读
      e.preventDefault();
      mainAgree.checked = false;
      if(window.CalcElfPrivacy && window.CalcElfPrivacy.forceOpen){
        window.CalcElfPrivacy.forceOpen();
      }
    });
  }

  // 点击“我已阅读《隐私说明》”这行文字 → 同样弹窗
  if(privacyLine){
    privacyLine.addEventListener('click', function(e){
      e.preventDefault();
      if(window.CalcElfPrivacy && window.CalcElfPrivacy.forceOpen){
        window.CalcElfPrivacy.forceOpen();
      }
    });
  }
})();

