// v5.6.8：上传前在浏览器内压缩图片，避免 Vercel 4.5MB 请求体限制（413 Request Entity Too Large）
async function calfCompressImage(file){
  const targetBytes = 3.2*1024*1024; // base64 前的目标上限，留足 JSON 余量
  const maxSide = 1600;
  const dataUrl = await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});
  let bmp=null;
  try{ bmp = await createImageBitmap(file, {imageOrientation:'from-image'}); }catch(e){ bmp=null; }
  let w,h;
  if(bmp){ w=bmp.width; h=bmp.height; }
  else { const img=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=dataUrl;}); w=img.naturalWidth; h=img.naturalHeight; }
  const scale=Math.min(1, maxSide/Math.max(w,h));
  w=Math.round(w*scale); h=Math.round(h*scale);
  const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
  const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);
  if(bmp){ctx.drawImage(bmp,0,0,w,h);try{bmp.close&&bmp.close();}catch(e){}}
  else{const img=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=dataUrl;});ctx.drawImage(img,0,0,w,h);}
  let q=0.82, out=canvas.toDataURL('image/jpeg',q);
  while(out.length>targetBytes*1.37 && q>0.5){ q-=0.12; out=canvas.toDataURL('image/jpeg',q); }
  return {dataUrl:out, base64:out.split(',')[1], mime:'image/jpeg'};
}
