// v5.10 照片+文字共存：有图时文字视为补充说明，不删图；动态切换标签/占位符/角标
function refreshNoteModeUI(){
  const hasImg=!!(imageBase64||($('file')&&$('file').files&&$('file').files.length));
  const eu=extraUi();
  const label=$('textLabel'), ta=$('text'), badge=$('imgNoteBadge');
  if(hasImg){
    if(label)label.textContent=eu.textLabelWithImg;
    if(ta)ta.placeholder=eu.textPlaceholderWithImg;
    if(badge){badge.textContent='📷 '+eu.imgBadge;badge.style.display='inline-block';}
  }else{
    if(label)label.textContent=t('text');
    if(ta)ta.placeholder=t('placeholder');
    if(badge)badge.style.display='none';
  }
}
function clearInputImage(showHint){
  if(imageBase64||($('file')&&$('file').files&&$('file').files.length)){
    imageBase64=null;imageMimeOut=null;
    if($('file'))$('file').value='';
    const pv=$('preview');if(pv)pv.style.display='none';
    const pi=$('previewImg');if(pi)pi.src='';
    if(showHint)toast(inputHint('text'));
    refreshNoteModeUI();
    return true;
  }
  return false;
}
async function setInputImageFile(f){
  if(!f)return;
  if(!/^image\//.test(f.type||''))return;
  if(f.size>15*1024*1024){toast(t('tooLarge'));return}
  // 选了/贴了图片：以图片为准，清空文字
  if($('text')&&$('text').value.trim()){ $('text').value=''; toast(inputHint('img')); }
  try{
    toast(currentLang&&(currentLang==='zh-CN'||currentLang==='zh-TW')?'正在压缩图片…':'Compressing image…');
    const c=await calfCompressImage(f);
    imageBase64=c.base64; imageMimeOut=c.mime;
    $('previewImg').src=c.dataUrl;$('preview').style.display='block';
  }catch(err){ console.error('image compress failed',err);
    const r=new FileReader();r.onload=()=>{imageBase64=r.result.split(',')[1];imageMimeOut=f.type||'image/jpeg';$('previewImg').src=r.result;$('preview').style.display='block'};r.readAsDataURL(f);
  }
  refreshNoteModeUI();
}
if($('file'))$('file').onchange=e=>{ const f=e.target.files[0]; if(f)setInputImageFile(f); };
// v5.10 修复：文字输入/语音追加时不再删除已附照片；文字视为补充说明
if($('text')){
  $('text').addEventListener('input',()=>{ refreshNoteModeUI(); });
  $('text').addEventListener('paste',e=>{
    const items=e.clipboardData&&e.clipboardData.items; if(!items)return;
    for(const it of items){ if(it.kind==='file'&&/^image\//.test(it.type||'')){ const f=it.getAsFile(); if(f){ e.preventDefault(); setInputImageFile(f); return; } } }
  });
}
